code.C:
#include <stdio.h>
int main() {
    double w, h; if (scanf("%lf %lf", &w, &h) != 2) return 0;
    double bmi = w / (h * h);
    if (bmi < 18.0) puts("0");
    else if (bmi < 25.0) puts("1");
    else if (bmi < 30.0) puts("2");
    else if (bmi < 40.0) puts("3");
    else puts("4");
    return 0;
}

